def top_k_frequent(items, k):
    if k <= 0:
        return []
    freq = {}
    for item in items:
        freq[item] = freq.get(item, 0) + 1
    distinct = list(freq.items())
    distinct.sort(key=lambda x: (-x[1], x[0]))
    if k > len(distinct):
        k = len(distinct)
    return [item for item, _ in distinct[:k]]
